<?php
declare(strict_types=1);

function hr17_schema(App $app):void {
    $tables=[
      'fisitaap_employees_r17'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,identification VARCHAR(40) NOT NULL,birth_date DATE NULL,nationality VARCHAR(80) NULL,civil_status VARCHAR(60) NULL,occupation VARCHAR(120) NULL,address TEXT NULL,phone VARCHAR(40) NULL,emergency_name VARCHAR(150) NULL,emergency_phone VARCHAR(40) NULL,job_title VARCHAR(150) NOT NULL,start_date DATE NOT NULL,end_date DATE NULL,contract_type VARCHAR(24) NOT NULL DEFAULT "indefinite",workplace VARCHAR(250) NULL,salary DECIMAL(15,2) NOT NULL DEFAULT 0,pay_frequency VARCHAR(20) NOT NULL DEFAULT "monthly",workday VARCHAR(20) NOT NULL DEFAULT "day",weekly_days INT NOT NULL DEFAULT 6,ccss_number VARCHAR(60) NULL,insurance_reference VARCHAR(100) NULL,bank_account VARCHAR(100) NULL,dependents TEXT NULL,contract_notes TEXT NULL,leave_opening DECIMAL(9,3) NOT NULL DEFAULT 0,leave_asof DATE NULL,is_active TINYINT NOT NULL DEFAULT 1,revision INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY employee_user(tenant_id,user_id),UNIQUE KEY employee_identity(tenant_id,identification),INDEX scope(tenant_id,is_active,id)',
      'fisitaap_schedules_r17'=>'tenant_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,weekday INT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,break_minutes INT NOT NULL DEFAULT 0,paid_break TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(employee_id,weekday),INDEX scope(tenant_id,employee_id)',
      'fisitaap_attendance_r17'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,device_id BIGINT UNSIGNED NULL,event_type VARCHAR(20) NOT NULL,marked_at DATETIME NOT NULL,source VARCHAR(20) NOT NULL,recorded_by BIGINT UNSIGNED NOT NULL,request_key CHAR(32) NOT NULL,payload_hash CHAR(64) NOT NULL,notice VARCHAR(250) NULL,reason VARCHAR(500) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY once_per_request(tenant_id,request_key),INDEX scope(tenant_id,employee_id,marked_at,id)',
      'fisitaap_attendance_changes_r17'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,attendance_id BIGINT UNSIGNED NOT NULL,new_time DATETIME NOT NULL,reason VARCHAR(500) NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX scope(tenant_id,attendance_id,id)',
      'fisitaap_leave_r17'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,days DECIMAL(9,3) NOT NULL,day_dates TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT "assigned",note VARCHAR(500) NULL,created_by BIGINT UNSIGNED NOT NULL,cancel_reason VARCHAR(500) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX scope(tenant_id,employee_id,start_date)',
      'fisitaap_salaries_r17'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,ordinary DECIMAL(15,2) NOT NULL,extraordinary DECIMAL(15,2) NOT NULL DEFAULT 0,note VARCHAR(500) NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY period(employee_id,start_date,end_date),INDEX scope(tenant_id,employee_id,start_date)',
      'fisitaap_hr_calculations_r17'=>'id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,input_json LONGTEXT NOT NULL,result_json LONGTEXT NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX scope(tenant_id,employee_id,id)',
    ];
    foreach($tables as $table=>$definition)$app->db->exec('CREATE TABLE IF NOT EXISTS '.$table.' ('.$definition.') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
    foreach(['contract_date'=>'DATE NULL','contract_place'=>'VARCHAR(250) NULL','sex'=>'VARCHAR(40) NULL','weekly_rest_paid'=>'TINYINT NOT NULL DEFAULT 1'] as $column=>$definition)if(!$app->one('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME="fisitaap_employees_r17" AND COLUMN_NAME=?',[$column]))$app->db->exec('ALTER TABLE fisitaap_employees_r17 ADD '.$column.' '.$definition);
}
function hr17_date(string $v):DateTimeImmutable {
    $d=DateTimeImmutable::createFromFormat('!Y-m-d',$v,new DateTimeZone('America/Costa_Rica'));if(!$d||$d->format('Y-m-d')!==$v)throw new DomainException('Escribe una fecha válida.');return $d;
}
function hr17_employee(App $app,int $tenant,int $id,bool $lock=false):array {
    $projection=r19_ready($app)?'COALESCE(u.name,e.name_r19) name,COALESCE(u.email,e.email_r19) email':'u.name,u.email';$e=$app->one('SELECT e.*,'.$projection.',u.username_r17,u.role,u.is_active user_active FROM fisitaap_employees_r17 e LEFT JOIN users u ON u.id=e.user_id AND u.tenant_id=e.tenant_id WHERE e.tenant_id=? AND e.id=?'.($lock?' FOR UPDATE':''),[$tenant,$id]);if(!$e)throw new DomainException('Empleado no disponible en este negocio.');return $e;
}
function hr17_events(App $app,int $tenant,int $id):array {
    return $app->all('SELECT a.*,COALESCE(c.new_time,a.marked_at) effective_at,c.reason correction_reason,c.actor_id corrected_by FROM fisitaap_attendance_r17 a LEFT JOIN fisitaap_attendance_changes_r17 c ON c.id=(SELECT MAX(cc.id) FROM fisitaap_attendance_changes_r17 cc WHERE cc.attendance_id=a.id AND cc.tenant_id=a.tenant_id) WHERE a.tenant_id=? AND a.employee_id=? ORDER BY effective_at,a.id',[$tenant,$id]);
}
function hr17_next(?string $event):array {return match($event){null,'out'=>['in'=>'Entrada'],'in','resume'=>['break'=>'Iniciar pausa','out'=>'Salida'],'break'=>['resume'=>'Regresar de pausa','out'=>'Salida'],default=>[]};}
function hr17_sequence(array $events):void {
    $previous=null;$time=null;foreach($events as $event){if(!isset(hr17_next($previous)[$event['event_type']]))throw new DomainException('La secuencia de marcas no es válida. Revisa entrada, pausa, regreso y salida.');if($time!==null&&$event['effective_at']<=$time)throw new DomainException('Cada marca debe tener una hora posterior a la anterior.');$previous=$event['event_type'];$time=$event['effective_at'];}
}
function hr17_device(App $app,array $u):array {
    $g=$_SESSION['native180']??[];
    if(($g['session_expires']??0)<time()||($g['user']??0)!==(int)$u['id']||($g['tenant']??0)!==(int)$u['tenant_id']||empty($g['print']))throw new DomainException('Marcar requiere FISITAAP Windows o Android instalado y vinculado.');
    $d=$app->one('SELECT id,branch_id FROM fisitaap_r2_devices WHERE id=? AND tenant_id=? AND token_hash=? AND is_active=1',[$g['device']??0,$u['tenant_id'],$g['token_hash']??'']);if(!$d||!empty($GLOBALS['demo_context']))throw new DomainException('El equipo no está autorizado para registrar marcas reales.');return $d;
}
function hr17_clock_api(App $app):never {
    $session=require_login(['tenant_admin','manager','editor','cashier','kitchen']);$t=$app->one('SELECT * FROM tenants WHERE id=? AND is_active=1',[$session['tenant_id']]);if(!$t||!module_enabled_v12($app,$t,'personnel'))json_response(['ok'=>false,'error'=>'Control de personal no está disponible.'],403);
    verify_csrf();
    try{
        $device=hr17_device($app,$session);$login=mb_strtolower(trim((string)($_POST['login']??'')));$key=(string)($_POST['request_key']??'');
        if(!rate_limit_persistent($app,'attendance_credentials',client_identity($t['id'].':'.$login),12,300))throw new DomainException('Demasiados intentos. Espera cinco minutos.');
        $u=r17_staff_identity($app,$login,(int)$t['id']);if(!$u||(int)$u['tenant_id']!==(int)$t['id']||!password_verify((string)($_POST['password']??''),$u['password_hash']))throw new DomainException('Usuario o contraseña incorrectos para este negocio.');
        $app->db->beginTransaction();$e=$app->one('SELECT * FROM fisitaap_employees_r17 WHERE tenant_id=? AND user_id=? AND is_active=1 FOR UPDATE',[$t['id'],$u['id']]);if(!$e||$e['start_date']>date('Y-m-d')||($e['end_date']&&$e['end_date']<date('Y-m-d')))throw new DomainException('Este usuario no tiene un expediente laboral activo.');
        $events=hr17_events($app,(int)$t['id'],(int)$e['id']);$last=$events?end($events):null;$next=hr17_next($last['event_type']??null);
        if(($_POST['action']??'')==='inspect'){$app->db->commit();json_response(['ok'=>true,'name'=>$u['name'],'next'=>$next,'previous'=>$last?['label'=>hr17_labels()[$last['event_type']],'time'=>$last['effective_at']]:null]);}
        $event=(string)($_POST['event_type']??'');if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new DomainException('Recarga el formulario antes de marcar.');
        $hash=hash('sha256',$e['id'].'|'.$event.'|'.$device['id']);$old=$app->one('SELECT * FROM fisitaap_attendance_r17 WHERE tenant_id=? AND request_key=?',[$t['id'],$key]);
        if($old){if(!hash_equals($old['payload_hash'],$hash))throw new DomainException('Esa solicitud ya corresponde a otra marca.');$app->db->commit();json_response(['ok'=>true,'duplicate'=>true,'message'=>hr17_labels()[$old['event_type']].' registrada a las '.$old['marked_at']]);}
        if(!isset($next[$event]))throw new DomainException('La marca anterior cambió. Consulta de nuevo antes de marcar.');
        if($last&&time()-strtotime($last['effective_at'])<30)throw new DomainException('La marca anterior acaba de guardarse. Espera 30 segundos para registrar otra.');
        if($last&&$last['event_type']!=='out'&&time()-strtotime($last['effective_at'])>86400)throw new DomainException('Hay una jornada abierta de más de 24 horas. Solicita corregir la marca faltante antes de continuar.');
        $notice='';$schedule=$app->one('SELECT * FROM fisitaap_schedules_r17 WHERE tenant_id=? AND employee_id=? AND weekday=?',[$t['id'],$e['id'],date('N')]);
        if(!$schedule)$notice='Marca fuera de un día programado; requiere revisión.';
        elseif($event==='in'&&strtotime(date('Y-m-d').' '.$schedule['start_time'])+300<time())$notice='Entrada posterior al horario programado. Revisar justificación; no aplica sanciones automáticas.';
        $app->exec('INSERT INTO fisitaap_attendance_r17(tenant_id,employee_id,branch_id,device_id,event_type,marked_at,source,recorded_by,request_key,payload_hash,notice) VALUES(?,?,?,?,?,NOW(),"native",?,?,?,?)',[$t['id'],$e['id'],$device['branch_id'],$device['id'],$event,$u['id'],$key,$hash,$notice?:null]);$id=(int)$app->db->lastInsertId();qa180_audit($app,$u,'attendance','employee',(int)$e['id'],hr17_labels()[$event].' registrada en equipo autorizado');$saved=$app->one('SELECT marked_at FROM fisitaap_attendance_r17 WHERE id=?',[$id]);$app->db->commit();json_response(['ok'=>true,'message'=>hr17_labels()[$event].' registrada: '.$saved['marked_at'].($notice?' · '.$notice:'')]);
    }catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();json_response(['ok'=>false,'error'=>$e instanceof PDOException?'No se pudo guardar la marca. Consulta antes de repetir.':$e->getMessage()],422);}
}
function hr17_labels():array {return ['in'=>'Entrada','break'=>'Pausa','resume'=>'Regreso','out'=>'Salida'];}
function hr17_save_employee(App $app,array $u,array $t):int {
    $separate=r19_ready($app);if(!$separate)require_module_v12($app,$t,'team');$id=(int)($_POST['id']??0);$old=$id?hr17_employee($app,(int)$t['id'],$id,true):null;
    if($old&&(int)($_POST['revision']??-1)!==(int)$old['revision'])throw new DomainException('El expediente cambió. Recarga antes de editar.');
    $name=trim((string)($_POST['name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$username=mb_strtolower(trim((string)($_POST['username']??'')));$password=(string)($_POST['password']??'');
    if($name===''||mb_strlen($name)>150)throw new DomainException('Completa el nombre del empleado.');
    $uid=$old?(int)$old['user_id']:(int)($_POST['link_user_id']??0);
    $member=$uid?$app->one('SELECT * FROM users WHERE id=? AND tenant_id=? AND role IN("tenant_admin","manager","editor","cashier","kitchen") FOR UPDATE',[$uid,$t['id']]):null;if($uid&&!$member)throw new DomainException('Selecciona un usuario de este negocio.');
    if(!$separate&&$member&&$member['role']==='tenant_admin')throw new DomainException('El dueño conserva su cuenta. Registra únicamente cuentas de colaboradores en este módulo.');
    if($separate){if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new DomainException('Escribe un correo de contacto válido.');}
    else {
    r17_email_unique($app,$email,$uid);
    if($username===''||(!preg_match('/^[a-z][a-z0-9._-]{2,79}$/D',$username)||$app->one('SELECT id FROM users WHERE tenant_id=? AND username_r17=? AND id<>?',[$t['id'],$username,$uid])))throw new DomainException('Usa un alias único, de 3 a 80 caracteres (único en tu empresa), que empiece con una letra.');
    $role=(string)($_POST['role']??'cashier');if(!in_array($role,['manager','editor','cashier','kitchen'],true)||($role==='kitchen'&&!r17_menu($t)))throw new DomainException('Selecciona un perfil válido para esta tienda.');
    if(($password!==''||!$member)&&(strlen($password)<4||strlen($password)>72))throw new DomainException('La contraseña debe tener de 4 a 72 caracteres.');
    }
    $branch=(int)($_POST['branch_id']??0);if(!$app->one('SELECT id FROM branches WHERE id=? AND tenant_id=? AND is_active=1',[$branch,$t['id']]))throw new DomainException('Selecciona una sucursal activa.');
    $identity=trim((string)($_POST['identification']??''));$job=trim((string)($_POST['job_title']??''));if($identity===''||strlen($identity)>40||$job===''||mb_strlen($job)>150)throw new DomainException('Completa identificación y puesto.');
    $start=hr17_date((string)($_POST['start_date']??''));$end=trim((string)($_POST['end_date']??''));if($end!==''&&hr17_date($end)<$start)throw new DomainException('La salida no puede ser anterior al ingreso.');
    $birth=trim((string)($_POST['birth_date']??''));if($birth!==''&&(hr17_date($birth)>$start||hr17_date($birth)>new DateTimeImmutable('-15 years')))throw new DomainException('Revisa la fecha de nacimiento. El trabajo adolescente requiere revisión legal especializada.');
    $contract=(string)($_POST['contract_type']??'indefinite');if(!in_array($contract,['indefinite','fixed','work'],true))throw new DomainException('Tipo de contrato inválido.');$workday=(string)($_POST['workday']??'day');if(!in_array($workday,['day','night','mixed'],true))throw new DomainException('Jornada inválida.');
    $salary=r2_number($_POST['salary']??0,0,999999999);$days=(int)($_POST['weekly_days']??6);if($days<1||$days>6)throw new DomainException('Define entre uno y seis días de trabajo por semana.');
    $frequency=(string)($_POST['pay_frequency']??'monthly');if(!in_array($frequency,['monthly','biweekly','weekly','daily'],true))throw new DomainException('Periodicidad inválida.');
    $phone=mb_substr(trim((string)($_POST['phone']??'')),0,40);$active=isset($_POST['is_active'])?1:0;
    if($separate){if($member&&$member['role']==='tenant_admin'&&!$active)throw new DomainException('El propietario conserva su acceso activo. No desactives su expediente asociado.');if($uid){$app->exec('UPDATE users SET name=?,phone=? WHERE id=? AND tenant_id=?',[$name,$phone,$uid,$t['id']]);if(!$active)$app->exec('UPDATE users SET is_active=0 WHERE id=? AND tenant_id=?',[$uid,$t['id']]);}}else {
    if($uid){$app->exec('UPDATE users SET name=?,email=?,phone=?,username_r17=?,is_active=? WHERE id=? AND tenant_id=?',[$name,$email,$phone,$username?:null,$active,$uid,$t['id']]);
        // Assigned custom permissions retain their manager adapter and original base profile.
        if($app->one('SELECT user_id FROM fisitaap_r1_user_roles WHERE tenant_id=? AND user_id=?',[$t['id'],$uid]))$app->exec('UPDATE fisitaap_r1_user_roles SET previous_role=? WHERE tenant_id=? AND user_id=?',[$role,$t['id'],$uid]);else $app->exec('UPDATE users SET role=? WHERE id=? AND tenant_id=?',[$role,$uid,$t['id']]);
        if($password!=='')$app->exec('UPDATE users SET password_hash=?,force_password_change=0 WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$uid]);
    }else{$app->exec('INSERT INTO users(tenant_id,name,email,phone,username_r17,password_hash,role,is_active,force_password_change) VALUES(?,?,?,?,?,?,?,?,0)',[$t['id'],$name,$email,$phone,$username?:null,password_hash($password,PASSWORD_DEFAULT),$role,$active]);$uid=(int)$app->db->lastInsertId();}
    }
    $data=['user_id'=>$uid?:null,'branch_id'=>$branch,'identification'=>$identity,'birth_date'=>$birth?:null,'job_title'=>$job,'start_date'=>$start->format('Y-m-d'),'end_date'=>$end?:null,'contract_type'=>$contract,'salary'=>$salary,'pay_frequency'=>$frequency,'workday'=>$workday,'weekly_days'=>$days,'phone'=>$phone,'is_active'=>$active];
    if($separate){$data['name_r19']=$name;$data['email_r19']=$email?:null;}
    foreach(['sex'=>40,'contract_place'=>250,'nationality'=>80,'civil_status'=>60,'occupation'=>120,'address'=>2000,'emergency_name'=>150,'emergency_phone'=>40,'workplace'=>250,'ccss_number'=>60,'insurance_reference'=>100,'bank_account'=>100,'dependents'=>2000,'contract_notes'=>3000] as $key=>$length)$data[$key]=mb_substr(trim((string)($_POST[$key]??'')),0,$length);
    $contractDate=trim((string)($_POST['contract_date']??''));$data['contract_date']=$contractDate!==''?hr17_date($contractDate)->format('Y-m-d'):null;$data['weekly_rest_paid']=isset($_POST['weekly_rest_paid'])?1:0;
    $opening=(string)($_POST['leave_opening']??'0');if(!is_numeric($opening)||abs((float)$opening)>1000)throw new DomainException('Revisa el saldo inicial de vacaciones.');$data['leave_opening']=(float)$opening;$asof=trim((string)($_POST['leave_asof']??''));$data['leave_asof']=$asof!==''?hr17_date($asof)->format('Y-m-d'):null;if($asof!==''&&hr17_date($asof)<$start)throw new DomainException('El saldo inicial no puede ser anterior al ingreso.');
    if($old&&((float)$old['leave_opening']!==$data['leave_opening']||(string)$old['leave_asof']!==(string)$data['leave_asof'])&&mb_strlen(trim((string)($_POST['balance_reason']??'')))<8)throw new DomainException('Explica el motivo del ajuste de saldo inicial.');
    if($id){$app->exec('UPDATE fisitaap_employees_r17 SET '.implode(',',array_map(fn($k)=>$k.'=?',array_keys($data))).',revision=revision+1 WHERE id=? AND tenant_id=?',[...array_values($data),$id,$t['id']]);}
    else{$app->exec('INSERT INTO fisitaap_employees_r17(tenant_id,'.implode(',',array_keys($data)).') VALUES('.implode(',',array_fill(0,count($data)+1,'?')).')',[$t['id'],...array_values($data)]);$id=(int)$app->db->lastInsertId();}
    qa180_audit($app,$u,'employee_save','employee',$id,'Guardó el expediente de '.$name.(!empty($_POST['balance_reason'])?' · Ajuste de vacaciones: '.mb_substr((string)$_POST['balance_reason'],0,200):''));return $id;
}
function hr17_leave_balance(App $app,array $e,string $asof):array {
    $date=hr17_date($asof);$base=hr17_date((string)($e['leave_asof']?:$e['start_date']));if($date<$base)throw new DomainException('La fecha es anterior al corte del saldo inicial; usa un saldo verificado para ese periodo.');$stop=$e['end_date']&&hr17_date($e['end_date'])<$date?hr17_date($e['end_date']):$date;$days=max(0,(int)$base->diff($stop)->format('%r%a'));
    $earned=$days/350*(2*(int)$e['weekly_days']);$taken=(float)$app->one('SELECT COALESCE(SUM(days),0) n FROM fisitaap_leave_r17 WHERE tenant_id=? AND employee_id=? AND status="assigned" AND start_date>=? AND start_date<=?',[$e['tenant_id'],$e['id'],$base->format('Y-m-d'),$asof])['n'];
    return ['opening'=>(float)$e['leave_opening'],'earned'=>round($earned,3),'assigned'=>$taken,'available'=>round((float)$e['leave_opening']+$earned-$taken,3),'basis'=>'Saldo estimado: 2 semanas ('.(2*(int)$e['weekly_days']).' días laborables) por 50 semanas. Verifica continuidad, régimen y saldos anteriores.'];
}
function hr17_salary_sum(App $app,array $e,string $from,string $to):array {
    $start=hr17_date($from);$end=hr17_date($to);$sum=0;$periods=[];$covered=0;
    foreach($app->all('SELECT * FROM fisitaap_salaries_r17 WHERE tenant_id=? AND employee_id=? AND end_date>=? AND start_date<=? ORDER BY start_date',[$e['tenant_id'],$e['id'],$from,$to]) as $p){$s=hr17_date($p['start_date']);$f=hr17_date($p['end_date']);$left=max($start,$s);$right=min($end,$f);$days=(int)$left->diff($right)->days+1;$full=(int)$s->diff($f)->days+1;$gross=((float)$p['ordinary']+(float)$p['extraordinary'])*$days/$full;$sum+=$gross;$covered+=$days;$periods[]=['from'=>$left->format('Y-m-d'),'to'=>$right->format('Y-m-d'),'gross'=>round($gross,2)];}
    return ['gross'=>round($sum,2),'covered_days'=>$covered,'periods'=>$periods];
}
function hr17_calculate(App $app,array $e,array $input):array {
    $date=hr17_date((string)($input['asof']??date('Y-m-d')));$start=hr17_date($e['start_date']);if($e['end_date']&&$date>hr17_date($e['end_date']))throw new DomainException('Usa la fecha de salida del empleado como corte.');if($date<$start)throw new DomainException('La fecha de cálculo debe ser posterior al ingreso.');
    $kind=(string)($input['kind']??'settlement');if(!in_array($kind,['aguinaldo','vacations','settlement'],true))throw new DomainException('Cálculo no disponible.');
    $year=(int)$date->format('Y');$periodStart=hr17_date(($date->format('m-d')>='12-01'?$year:$year-1).'-12-01');$periodEnd=$periodStart->modify('+1 year -1 day');$aguFrom=max($periodStart,$start);$aguTo=min($periodEnd,$date);$agu=hr17_salary_sum($app,$e,$aguFrom->format('Y-m-d'),$aguTo->format('Y-m-d'));
    $months=$start->diff($date)->y*12+$start->diff($date)->m;$years=$start->diff($date)->y;$remMonths=$start->diff($date)->m;$remDays=$start->diff($date)->d;
    $sixFrom=max($start,$date->modify('-6 months +1 day'));$six=hr17_salary_sum($app,$e,$sixFrom->format('Y-m-d'),$date->format('Y-m-d'));$monthsEquivalent=0;for($cursor=$sixFrom;$cursor<=$date;$cursor=$cursor->modify('first day of next month')){$right=min($date,$cursor->modify('last day of this month'));$monthsEquivalent+=((int)$cursor->diff($right)->days+1)/(int)$cursor->format('t');}$monthsEquivalent=max(1/30,$monthsEquivalent);$avg=$six['covered_days']>0?$six['gross']/$monthsEquivalent:0;
    // Users enter gross monthly equivalent separately for incomplete records; never silently use net pay.
    $override=$input['average_monthly']??'';if($override!=='')$avg=r2_number($override,0,999999999);$daily=$avg/30;
    $reason=(string)($input['reason']??'resignation');if(!in_array($reason,['resignation','with_responsibility','without_responsibility'],true))throw new DomainException('Indica la causa de salida.');
    $preDays=$months<3?0:($months<6?7:($months<12?15:30));$cesDays=0;
    if($months>=3&&$months<6)$cesDays=7;elseif($months>=6&&$months<12)$cesDays=14;elseif($years>=1){$table=[1=>19.5,2=>20,3=>20.5,4=>21,5=>21.24,6=>21.5,7=>22,8=>22,9=>22,10=>21.5,11=>21,12=>20.5];$credited=$years+(($remMonths>6||($remMonths===6&&$remDays>0))?1:0);for($i=max(1,$credited-7);$i<=$credited;$i++)$cesDays+=$table[$i]??20;}
    if($e['contract_type']!=='indefinite'&&$kind==='settlement')throw new DomainException('Los contratos por plazo u obra requieren cálculo específico del artículo 31. No se aplica automáticamente la tabla de contrato indefinido.');
    $vac=hr17_leave_balance($app,$e,$date->format('Y-m-d'));$vacDays=max(0,$vac['available']);
    if(isset($input['vacation_days'])&&$input['vacation_days']!=='')$vacDays=r2_number($input['vacation_days'],0,1000);
