    if(!$restPaid){$vacDaily=$vacDaily*7/max(1,(int)$e['weekly_days']);}
    $pre=$reason==='with_responsibility'&&empty($input['notice_worked'])?$preDays*$daily:0;$ces=$reason==='with_responsibility'?$cesDays*$daily:0;
    $warnings=['Estimación para revisión de planilla; no genera pagos ni finiquito.','La vigencia de las fuentes oficiales no pudo comprobarse en este entorno; verifica con MTSS antes de liquidar.','La base de vacaciones requiere verificar actividad comercial, días pagados, interrupciones y beneficios contractuales.'];
    if($six['covered_days']<(int)$sixFrom->diff($date)->days+1)$warnings[]='Historial de salarios incompleto en los últimos seis meses. Completa los periodos o indica una base mensual verificada.';
    if(!$agu['periods'])$warnings[]='Sin salarios registrados para aguinaldo. Un resultado de cero no prueba que no exista obligación.';
    return ['asof'=>$date->format('Y-m-d'),'kind'=>$kind,'service'=>['years'=>$years,'months'=>$remMonths,'days'=>$remDays],'salary_monthly'=>round($avg,2),'salary_daily'=>round($daily,4),'aguinaldo_from'=>$aguFrom->format('Y-m-d'),'aguinaldo_to'=>$aguTo->format('Y-m-d'),'aguinaldo_gross'=>$agu['gross'],'aguinaldo'=>round($agu['gross']/12,2),'notice_days'=>$preDays,'notice'=>round($pre,2),'severance_days'=>round($cesDays,2),'severance'=>round($ces,2),'vacation_days'=>round($vacDays,3),'vacation_paid_days'=>round($vacPaidDays,4),'vacation_rest_paid'=>$restPaid,'vacation_daily'=>round($vacDaily,4),'vacations'=>round($vacPaidDays*$vacDaily,2),'total'=>round(($kind!=='vacations'?$agu['gross']/12:0)+($kind==='settlement'?$pre+$ces:0)+($kind!=='aguinaldo'?$vacPaidDays*$vacDaily:0),2),'warnings'=>$warnings,'rule_version'=>'CR-CT-28-29-136-138-139-152-153-156-157 + Ley 2412; referencia de fórmulas R17','salary_periods'=>$agu['periods']];
}
