function hr17_schedule_ui(App $app,array $t,array $e,bool $may):void {
    $rows=[];foreach($app->all('SELECT * FROM fisitaap_schedules_r17 WHERE tenant_id=? AND employee_id=?',[$t['id'],$e['id']]) as $r)$rows[$r['weekday']]=$r;
    echo '<section class="card admin-card"><h2>Horario semanal</h2><p>Horario ordinario estándar. Las jornadas excepcionales requieren revisión. En turnos nocturnos una salida menor que la entrada pertenece al día siguiente. La pausa remunerada cuenta como tiempo de trabajo.</p><form method="post">'.csrf_field().pos_hidden_148('action','schedule').'<div class="table-wrap"><table class="table"><tr><th>Día laborable</th><th>Entrada</th><th>Salida</th><th>Pausa (min)</th><th>Remunerada</th></tr>';
    foreach([1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'] as $n=>$label){$r=$rows[$n]??[];echo '<tr><td><label><input type="checkbox" name="workday['.$n.']" '.($r?'checked':'').'> '.$label.'</label></td><td><input aria-label="Entrada '.$label.'" class="input" type="time" name="start['.$n.']" value="'.e(substr($r['start_time']??'08:00',0,5)).'"></td><td><input aria-label="Salida '.$label.'" class="input" type="time" name="end['.$n.']" value="'.e(substr($r['end_time']??'16:00',0,5)).'"></td><td><input aria-label="Pausa '.$label.'" class="input" type="number" min="0" max="240" name="break['.$n.']" value="'.(int)($r['break_minutes']??30).'"></td><td><input aria-label="Pausa remunerada '.$label.'" type="checkbox" name="paid['.$n.']" '.(!empty($r['paid_break'])?'checked':'').'></td></tr>';}
    echo '</table></div>'.($may?'<button class="btn">Guardar horario</button>':'').'</form><p>Las diferencias de horario generan avisos; no descuentan salario ni aplican sanciones automáticamente.</p></section>';
}
function hr17_marks_ui(App $app,array $t,array $e,bool $may):void {
    $events=hr17_events($app,(int)$t['id'],(int)$e['id']);$seconds=0;$working=null;foreach($events as $r){$at=strtotime($r['effective_at']);if(in_array($r['event_type'],['in','resume'],true))$working=$at;elseif($working!==null){$seconds+=max(0,$at-$working);$working=null;}}
    echo '<section class="card admin-card"><h2>Bitácora de marcas</h2><p><strong>'.number_format($seconds/3600,2,',','').' horas registradas</strong> en tramos cerrados. Excluye pausas marcadas y jornadas sin salida; el pago de pausas y horas extraordinarias requiere revisión.</p><div class="table-wrap"><table class="table"><tr><th>Tipo</th><th>Hora efectiva</th><th>Origen / equipo</th><th>Observaciones</th><th>Correcciones</th></tr>';
    foreach(array_slice(array_reverse($events),0,300) as $r){echo '<tr><td>'.hr17_labels()[$r['event_type']].'</td><td>'.e($r['effective_at']).($r['correction_reason']?'<small>Original: '.e($r['marked_at']).'</small>':'').'</td><td>'.($r['source']==='native'?'Aplicación instalada · #'.(int)$r['device_id']:'Ajuste administrativo').'</td><td>'.e($r['notice']??$r['reason']??'').'</td><td>';foreach($app->all('SELECT c.*,u.name FROM fisitaap_attendance_changes_r17 c JOIN users u ON u.id=c.actor_id WHERE c.tenant_id=? AND c.attendance_id=? ORDER BY c.id',[$t['id'],$r['id']]) as $change)echo '<small>'.e($change['new_time'].' · '.$change['name'].' · '.$change['reason']).'</small>';if($may)echo '<details><summary>Corregir hora</summary><form method="post">'.csrf_field().pos_hidden_148('action','correct_mark').pos_hidden_148('mark_id',$r['id']).field('Hora corregida','marked_at',str_replace(' ','T',substr($r['effective_at'],0,16)),true,'datetime-local').field('Justificación','reason','',true).'<button class="btn btn-light">Guardar ajuste</button></form></details>';echo '</td></tr>';}
    echo '</table></div></section>';
    if($may)echo '<section class="card admin-card"><h2>Registrar una marca omitida</h2><p>Solo para corregir omisiones justificadas. Se conserva quién la registró y el motivo.</p><form method="post">'.csrf_field().pos_hidden_148('action','manual_mark').'<label>Tipo<select class="input" name="event_type">'.implode('',array_map(fn($key,$label)=>'<option value="'.$key.'">'.$label.'</option>',array_keys(hr17_labels()),hr17_labels())).'</select></label>'.field('Fecha y hora real','marked_at','',true,'datetime-local').field('Justificación','reason','',true).'<button class="btn btn-light">Registrar omisión</button></form></section>';
}
function hr17_vacations_ui(App $app,array $t,array $e,bool $may):void {
    $b=hr17_leave_balance($app,$e,date('Y-m-d'));echo '<section class="card admin-card"><h2>Vacaciones</h2><div class="hr17-summary"><div><small>Saldo estimado</small><strong>'.e($b['available']).' días</strong></div><div><small>Devengado estimado</small><strong>'.e($b['earned']).'</strong></div><div><small>Asignado hasta hoy</small><strong>'.e($b['assigned']).'</strong></div></div><p>'.e($b['basis']).'</p>';
    if($may)echo '<form method="post">'.csrf_field().pos_hidden_148('action','vacation').'<div class="hr17-grid">'.field('Desde','from','',true,'date').field('Hasta','to','',true,'date').field('Observación','note','').'</div><p>Se cuentan los días laborables del horario y se reservan los ya asignados. Se excluyen los feriados nacionales del calendario estándar. Revisa traslados extraordinarios o regímenes especiales antes de asignar.</p><button class="btn">Asignar vacaciones</button></form>';echo '</section><section class="card admin-card"><h2>Asignaciones</h2>';
    foreach($app->all('SELECT * FROM fisitaap_leave_r17 WHERE tenant_id=? AND employee_id=? ORDER BY id DESC LIMIT 100',[$t['id'],$e['id']]) as $r){echo '<article class="r17-record"><strong>'.e($r['start_date'].' → '.$r['end_date']).'</strong><p>'.e($r['days']).' días · '.($r['status']==='assigned'?'Asignadas':'Anuladas').'</p><small>'.e($r['note']).'</small>';if($may&&$r['status']==='assigned')echo '<details><summary>Anular asignación</summary>'.r2_form('cancel_vacation').pos_hidden_148('leave_id',$r['id']).field('Motivo','reason','',true).'<button class="btn btn-light">Anular con justificación</button></form></details>';if($r['cancel_reason'])echo '<small>'.e($r['cancel_reason']).'</small>';echo '</article>';}echo '</section>';
}
function hr17_salaries_ui(App $app,array $t,array $e,bool $may):void {
    echo '<section class="card admin-card"><h2>Salarios brutos devengados</h2><p>Registra importes ordinarios y extraordinarios reales. No incluyas reintegros de gastos ni aguinaldo. Evita periodos superpuestos. Estos registros alimentan estimaciones; no ejecutan pagos.</p>';
    if($may)echo '<form method="post">'.csrf_field().pos_hidden_148('action','salary').'<div class="hr17-grid">'.field('Desde','from','',true,'date').field('Hasta','to','',true,'date').field('Salario ordinario bruto (₡)','ordinary',0,true,'number','.01').field('Salario extraordinario bruto (₡)','extraordinary',0,true,'number','.01').field('Observación / referencia de planilla','note','').'</div><button class="btn">Guardar salario</button></form>';echo '</section><section class="card admin-card"><div class="table-wrap"><table class="table"><tr><th>Periodo</th><th>Ordinario</th><th>Extraordinario</th><th>Referencia</th></tr>';foreach($app->all('SELECT * FROM fisitaap_salaries_r17 WHERE tenant_id=? AND employee_id=? ORDER BY start_date DESC LIMIT 200',[$t['id'],$e['id']]) as $r)echo '<tr><td>'.e($r['start_date'].' → '.$r['end_date']).'</td><td>'.money((float)$r['ordinary']).'</td><td>'.money((float)$r['extraordinary']).'</td><td>'.e($r['note']).'</td></tr>';echo '</table></div></section>';
}
function hr17_calculations_ui(App $app,array $t,array $e,bool $may):void {
    echo '<section class="card admin-card"><h2>Calculadora laboral · Costa Rica</h2><p>Estimaciones desglosadas para contrato indefinido, sujetas a salarios, continuidad, causa de salida y condiciones aplicables. No se emiten finiquitos ni se generan pagos.</p><details><summary>Fuentes, fórmulas y límites</summary><p>Código de Trabajo: artículos 28 y 29 (preaviso y cesantía), 136–139 (jornada), 152–157 (descanso y vacaciones). Aguinaldo en empresa privada: Ley 2412. La vigencia de las fuentes no pudo verificarse desde este entorno.</p><p>Preaviso: 7, 15 o 30 días según antigüedad. Cesantía: 7 días de 3 a menos de 6 meses, 14 de 6 a menos de 12 meses; desde un año aplica tabla legal y máximo de ocho años. Solo se incluye en despido con responsabilidad patronal.</p><p>Aguinaldo: bruto ordinario + extraordinario del 1 diciembre al 30 noviembre dividido entre 12. Vacaciones: saldo verificado o estimado según semanas de servicio, valorado con la base indicada. Los periodos parciales de salario se prorratean por días calendario.</p><a target="_blank" rel="noopener" href="https://www.mtss.go.cr/temas-laborales/">Consultar MTSS</a> · <a target="_blank" rel="noopener" href="https://pgrweb.go.cr/scij/Busqueda/Normativa/Normas/nrm_texto_completo.aspx?nValor1=1&amp;nValor2=8045">Código de Trabajo · SCIJ</a></details>';
    if($may)echo '<form method="post">'.csrf_field().pos_hidden_148('action','calculate').'<div class="hr17-grid"><label>Cálculo<select class="input" name="kind"><option value="settlement">Salida / despido</option><option value="aguinaldo">Aguinaldo proporcional</option><option value="vacations">Vacaciones</option></select></label>'.field('Fecha de corte','asof',date('Y-m-d'),true,'date').'<label>Causa de salida<select class="input" name="reason"><option value="resignation">Renuncia</option><option value="with_responsibility">Despido con responsabilidad patronal</option><option value="without_responsibility">Despido sin responsabilidad patronal</option></select></label>'.field('Base mensual bruta verificada (opcional)','average_monthly','',false,'number','.01').field('Días de vacaciones verificados (opcional)','vacation_days','',false,'number','.001').'</div><label><input type="checkbox" name="notice_worked"> El preaviso se trabaja o ya fue concedido</label><p>Si falta historial, completa salarios o indica una base verificada. La base mensual se divide entre 30 para el día salarial; vacaciones usa el historial de 50 semanas salvo base verificada. En pago mensual/quincenal se incluye el descanso semanal: dos semanas de vacaciones equivalen a 14 días remunerados, aunque el horario tenga 10 o 12 días laborables.</p><button class="btn">Calcular y guardar estimación</button></form>';echo '</section>';
    foreach($app->all('SELECT * FROM fisitaap_hr_calculations_r17 WHERE tenant_id=? AND employee_id=? ORDER BY id DESC LIMIT 10',[$t['id'],$e['id']]) as $row){$r=json_decode($row['result_json'],true);echo '<section class="card admin-card hr17-result"><header><small>ESTIMACIÓN #'.(int)$row['id'].' · '.e($row['created_at']).'</small><h2>'.e(['settlement'=>'Salida / despido','vacations'=>'Vacaciones','aguinaldo'=>'Aguinaldo'][$r['kind']]).'</h2></header><p>Antigüedad: '.(int)$r['service']['years'].' años, '.(int)$r['service']['months'].' meses, '.(int)$r['service']['days'].' días · Corte '.e($r['asof']).'</p><dl><dt>Base mensual utilizada</dt><dd>'.money((float)$r['salary_monthly']).'</dd><dt>Salarios para aguinaldo</dt><dd>'.money((float)$r['aguinaldo_gross']).' / 12</dd><dt>Aguinaldo proporcional</dt><dd>'.money((float)$r['aguinaldo']).'</dd>';
        if($r['kind']!=='aguinaldo')echo '<dt>Vacaciones: '.e($r['vacation_days']).' días laborables / '.e($r['vacation_paid_days']??$r['vacation_days']).' días remunerados × '.money((float)$r['vacation_daily']).'</dt><dd>'.money((float)$r['vacations']).'</dd>';
        if($r['kind']==='settlement')echo '<dt>Preaviso (según causa / cumplimiento)</dt><dd>'.money((float)$r['notice']).'</dd><dt>Cesantía (según causa)</dt><dd>'.money((float)$r['severance']).'</dd>';echo '<dt>Total estimado</dt><dd><strong>'.money((float)$r['total']).'</strong></dd></dl><details><summary>Supuestos y advertencias</summary><ul>';foreach($r['warnings'] as $warning)echo '<li>'.e($warning).'</li>';echo '</ul><p>'.e($r['rule_version']).'</p></details></section>';
    }
}
function hr17_holidays(int $year):array {
    $a=$year%19;$b=intdiv($year,100);$c=$year%100;$d=intdiv($b,4);$f=intdiv($b+8,25);$g=intdiv($b-$f+1,3);$h=(19*$a+$b-$d-$g+15)%30;$i=intdiv($c,4);$k=$c%4;$l=(32+2*($b%4)+2*$i-$h-$k)%7;$m=intdiv($a+11*$h+22*$l,451);$month=intdiv($h+$l-7*$m+114,31);$day=($h+$l-7*$m+114)%31+1;$easter=hr17_date(sprintf('%04d-%02d-%02d',$year,$month,$day));
    $out=[];foreach(['01-01'=>'Año Nuevo','04-11'=>'Juan Santamaría','05-01'=>'Día del Trabajo','07-25'=>'Anexión de Guanacaste','08-02'=>'Virgen de los Ángeles','08-15'=>'Día de la Madre','08-31'=>'Persona Negra y Cultura Afrocostarricense','09-15'=>'Independencia','12-01'=>'Abolición del Ejército','12-25'=>'Navidad'] as $date=>$name)$out[$year.'-'.$date]=$name;
    $out[$easter->modify('-3 days')->format('Y-m-d')]='Jueves Santo';$out[$easter->modify('-2 days')->format('Y-m-d')]='Viernes Santo';return $out;
}
